const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=$('#app');
const steps=['核心能力自評','教案與學習目標','影片與情境學習','虛擬角色互動','即時測驗','成果與教師回饋'];
const labels={MD:'醫師',RN:'護理師',DT:'營養師',PT:'物理治療師',OT:'職能治療師',RT:'醫事放射師',RSP:'呼吸治療師',RPH:'藥師',ST:'語言治療師',AUD:'聽力師',CP:'臨床心理師',MLS:'醫事檢驗師'};
const dims={CJ:'臨床判斷',PC:'評估與照護',COM:'病人溝通',TC:'團隊溝通',SAFE:'安全與倫理',HC:'全人照護'};
let state={user:null,entry:null,session:null,services:null,teacherDetail:null};
let authChannel=null;
try{authChannel=new BroadcastChannel('clinical-tutor-auth');authChannel.onmessage=event=>{if(event.data==='sign-in-required')showLogin(false);};}catch{}
async function verifyVisibleLogin(){const active=state.user;if(!active)return;try{const response=await fetch('/api/me',{credentials:'same-origin',cache:'no-store'});if(state.user!==active)return;if(response.status===401){showLogin(false);return;}if(response.ok){const current=await response.json();if(state.user===active&&(current.id!==active.id||current.role!==active.role))showLogin(false);}}catch{}}
window.addEventListener('focus',verifyVisibleLogin);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')verifyVisibleLogin();});
let voiceInput=null,disposeScene=null,conversationEpoch=0,conversationClosed=false,chatBusy=false;
let speechContext=null,speechFrame=null,patientAudio=null,avatar=null,voice=null,teacherTimer=null,videoTimer=null,draftTimer=null,draftQueue=Promise.resolve();
const toast=t=>{let el=$('#toast');el.textContent=t;el.style.display='block';clearTimeout(el._timer);el._timer=setTimeout(()=>el.style.display='none',4500);};
async function api(path,method='GET',body){const response=await fetch(path,{method,credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let data=await response.json();if(!response.ok){if(response.status===401&&state.user){state.user=null;showLogin();}throw new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));}return data;}
function cleanup(){conversationEpoch++;chatBusy=false;disposeLearningResources();voiceInput?.dispose();voiceInput=null;disposeScene?.();disposeScene=null;patientAudio?.pause();patientAudio=null;cancelAnimationFrame(speechFrame);speechContext?.close().catch(()=>{});speechContext=null;avatar?.dispose();avatar=null;voice?.disconnect();voice=null;clearInterval(teacherTimer);clearInterval(videoTimer);teacherTimer=null;videoTimer=null;}
function error(e){console.error(e);toast(e.message||String(e));let box=$('#page-error');if(box){box.className='error';box.textContent=e.message||String(e);}}
function heading(title,sub,badge=''){return `<div class="heading"><div><div class="eyebrow">CLINICAL LEARNING / ${state.user?.role==='admin'?'ADMIN':state.user?.role==='teacher'?'FACULTY':'LEARNER'}</div><h1>${esc(title)}</h1><p>${esc(sub+(state.session?.data?.legacy_import?' · v3 匯入紀錄，舊等級待教師認列':''))}</p></div>${badge}</div>`;}
function shell(body,step=0){
const previousTitle=document.querySelector('h1')?.textContent,isTeacher=state.user.role==='teacher',isAdmin=state.user.role==='admin',isStudent=state.user.role==='student',current=state.session?.step||0;
const role=isAdmin?'管理員':isTeacher?'教師':'學員';
app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">${brandMark()}<div><span class="brand-institution">中山醫學大學附設醫院</span><strong>迴旋梯智鏈</strong><small>CLINICAL LEARNING</small></div></div><div class="nav-caption">${isStudent?'我的學習空間':'平台工作空間'}</div><button data-action="home" class="nav-home ${step===0?'active':''}">${icon(isAdmin?'people':isTeacher?'chart':'home',20)}<span>${isAdmin?'帳號與職種管理':isTeacher?'教學監控總覽':'訓練首頁'}</span></button><button data-action="characters">${icon('people',20)}<span>虛擬角色圖鑑</span></button>${isAdmin?`<button data-action="admin-preview">${icon('clipboard',20)}<span>職種分級題庫預覽</span></button>`:''}${isStudent?`<div class="nav-caption journey-nav-title">六階段學習旅程</div>${steps.map((s,i)=>`<button data-action="navigate" data-step="${i+1}" class="${step===i+1?'active':''}" ${i+1!==current&&!(i+1===3&&current>=3)?'disabled':''}>${icon(stepIcons[i],20)}<span>${s}</span><small class="nav-index">${String(i+1).padStart(2,'0')}</small></button>`).join('')}`:''}<div class="sidebar-values"><span>自由</span><i></i><span>平等</span><i></i><span>博愛</span></div><div class="bottom"><button data-action="history" aria-label="${isAdmin?'重新整理管理台':isTeacher?'重新整理看板':'我的學習歷程'}">${icon(isStudent?'history':'chart',20)}<span>${isAdmin?'重新整理管理台':isTeacher?'重新整理看板':'我的學習歷程'}</span></button><button data-action="logout" aria-label="登出平台">${icon('logout',20)}<span>登出平台</span></button><div class="sidebar-edition">中山醫學大學附設醫院 · 教學試辦</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">${icon('grid',16)}<span>${isAdmin?'系統管理':isTeacher?'教學監控':'專業學習'}</span><span class="breadcrumb-slash">/</span><b>${state.session&&isStudent?esc(labels[state.session.profession]):isAdmin?'管理員工作台':isTeacher?'教師工作台':'迴旋梯智鏈'}</b></div><div class="topbar-account"><span class="badge role-badge">${role}</span><span class="account-avatar">${esc(state.user.display_name?.slice(0,1)||role.slice(0,1))}</span><span class="account-name">${esc(state.user.display_name)}</span><button class="logout-button" data-action="logout" aria-label="登出平台">${icon('logout',18)}<span>登出</span></button></div></header><div class="content"><div id="page-error" role="alert"></div>${isStudent&&step?learningTrack(steps,step):''}${body}<footer class="workspace-footer"><span>CHUNG SHAN MEDICAL UNIVERSITY HOSPITAL <b>·</b> CLINICAL LEARNING</span><span>教學・服務・研究</span></footer></div></main></div>`;
if(previousTitle!==document.querySelector('h1')?.textContent)window.scrollTo(0,0);
}
function showLogin(notify=true){
if(notify)authChannel?.postMessage('sign-in-required');
cleanup();state.user=null;state.session=null;state.entry=null;state.actors=null;state.services=null;state.teacherDetail=null;sessionStorage.removeItem('clinical-combo');
app.innerHTML=`<main class="login"><section class="login-art"><div class="login-university">${brandMark()}<div><strong>中山醫學大學附設醫院</strong><span>CHUNG SHAN MEDICAL UNIVERSITY HOSPITAL</span></div><span class="edition-tag">教學試辦</span></div><div class="login-story"><div class="eyebrow"><span></span>FROM KNOWLEDGE TO CARE</div><h1>讓每一次練習，<br>成為照護的<span>底氣。</span></h1><p>以人為本的專業學習，從理解自己開始。<br>在情境中練習，在回饋中成長。</p></div>${learningJourney()}<div class="login-values"><span><i class="value-dot blue"></i>自由探索</span><span><i class="value-dot red"></i>平等協作</span><span><i class="value-dot white"></i>博愛照護</span></div></section><section class="login-panel"><div class="login-form"><div class="login-welcome">${icon('spark',18)}<span>歡迎回到您的學習空間</span></div><div class="eyebrow login-product">CLINICAL TUTOR</div><h2>迴旋梯智鏈<br><small>醫事智慧訓練平台</small></h2><p class="login-intro">累積專業能力，讓每一步學習都有方向。</p><div id="page-error" role="alert"></div><form id="login-form"><label for="username">帳號 <span>ACCOUNT</span></label><div class="input-wrap">${icon('user',19)}<input id="username" name="username" autocomplete="username" placeholder="請輸入您的帳號" required></div><label for="password">密碼 <span>PASSWORD</span></label><div class="input-wrap">${icon('lock',19)}<input id="password" name="password" type="password" autocomplete="current-password" placeholder="請輸入密碼" required><button class="password-toggle" type="button" data-action="toggle-password" aria-label="顯示密碼" aria-pressed="false">${icon('eye',19)}</button></div><button class="login-submit" type="submit"><span>登入，開始專業成長</span>${icon('arrow',21)}</button></form><div class="login-role-row"><span>${icon('book',16)}學員訓練</span><span>${icon('chart',16)}教師工作台</span><span>${icon('shield',16)}管理員</span></div><div class="login-help">${icon('shield',19)}<p>帳號由管理員建立。登入後，系統會依您的身分<br class="desktop-break">開啟對應的學習或管理空間。</p></div><div class="login-footnote"><span>能力導向教育 · 跨專業學習</span><span>教材與評分規則待職類教師核定</span></div></div></section></main>`;
}
async function chooseProfession(filter='all'){
cleanup();state.session=null;state.entry=null;
const [cat,h]=await Promise.all([api('/api/catalog'),api('/api/history')]);
const shown=cat.combinations.filter(c=>filter==='all'||(filter==='training'?c.training_available:!c.training_available));
shell(`<section class="profession-hero"><div><div class="hero-kicker">YOUR PROFESSIONAL JOURNEY</div><h1>選擇您的專業，<br>開啟下一步成長。</h1><p>選擇本次訓練職種，從能力自評開始。<br>已經有學習紀錄？完成本次自評，即可接續原進度。</p><div class="hero-feature">${icon('shield',17)}<span>${h.access_grant?'全教材體驗授權：12職種與全部情境已解鎖。':'初次以 Level 1 題本起測，自評後分流；各職種獨立累積。'}</span></div></div><div class="profession-hero-art" aria-hidden="true"><div class="hero-art-ring"></div>${brandMark()}<span class="hero-art-tag tag-one">${icon('people',18)}跨專業協作</span><span class="hero-art-tag tag-two">${icon('chart',18)}看見學習成長</span></div></section><div class="catalog-summary"><div>${icon('people',21)}<strong>12</strong><span>專業職種</span></div><div>${icon('interaction',21)}<strong>06</strong><span>學習階段</span></div><div>${icon('book',21)}<strong>${cat.combinations.filter(c=>c.training_available).length.toString().padStart(2,'0')}</strong><span>職種已有肌少症教案</span></div></div><div class="catalog-section-heading"><div><div class="eyebrow">EXPLORE YOUR PROFESSION</div><h2>選擇本次訓練職種</h2></div><div class="catalog-filters" aria-label="職種內容篩選">${[['all','全部職種',12],['training','肌少症訓練',5],['assessment','肌少症僅自評',7]].map(([key,name,n])=>`<button class="${filter===key?'selected':''}" data-action="profession-filter" data-filter="${key}" aria-pressed="${filter===key}">${name}<span>${n}</span></button>`).join('')}</div></div><div class="profession-grid">${shown.map(c=>{const p=h.progress.find(x=>x.profession===c.profession&&x.topic===c.symptom),level=(h.learning_progress||[]).find(x=>x.profession===c.profession&&x.topic===c.symptom)?.level||h.access_grant?.level||1;return `<article class="card profession-card"><div class="profession-card-top"><span class="profession-icon">${icon(c.profession,30)}</span><span class="profession-code">${esc(c.profession)}</span></div><h2>${esc(c.profession_label)}</h2><p class="profession-description">${esc(professionDescriptions[c.profession])}</p><span class="content-status ${c.training_available?'available':'assessment-only'}"><i></i>${c.training_available?'肌少症教案已開放':'階段一自評已開放'}</span><div class="profession-level"><span>累積學習 <b>Level ${level}</b></span><span class="level-dots" aria-label="Level ${level}，共 5 級">${[1,2,3,4,5].map(n=>`<i class="${n<=level?'filled':''}"></i>`).join('')}</span></div><p class="profession-note">${c.training_available?'完成自評後，進入情境訓練或接續原進度。':'肌少症開放自評；可選擇其他適用情境進入訓練。'}</p><button class="profession-enter" data-action="topics" data-profession="${c.profession}" data-topic="${esc(c.symptom)}"><span>${p?'選擇情境／續訓':'選擇情境，開始自評'}</span>${icon('arrow',19)}</button></article>`;}).join('')}</div><div class="catalog-bottom-note">${icon('clipboard',21)}<p>每次重新登入輪替自評題，重新整理保留本次題目與草稿。<br>自評決定案例難度；累積使用與正確性獨立解鎖教材資訊；新增分級題目為待審草稿。</p></div>`);
}
async function enter(profession,topic='肌少症',newRound=false){cleanup();state.session=null;state.entry=await api('/api/entry','POST',{profession,topic,new_round:newRound});sessionStorage.setItem('clinical-combo',JSON.stringify({profession,topic}));if(state.entry.assessment_required)renderAssessment();else if(state.entry.resume_session_id)await loadSession(state.entry.resume_session_id);else await assessmentDetail(state.entry.attempt_id);}
function renderAssessment(){cleanup();const e=state.entry,s=e.snapshot,d=e.draft||{};shell(heading('Step 1　核心能力自評',labels[s.profession]+' · '+s.context,`<span class="badge">起測題本 Level ${e.snapshot.level}</span>`)+`<div class="note">${esc(e.note)}${!e.training_available?'<br>本職種目前完成範圍為階段一，後續肌少症教案待建置。':e.resume_session_id?`<br>既有訓練 #${e.resume_session_id} 已保留，自評完成後回到原步驟。`:'<br>完成後將顯示百分制自評分數，依分數安排 Level 1–5 案例難度；累積學習解鎖另行計算。'}</div><form id="assessment-form"><div class="card"><h2>${esc(s.form_title)}</h2><details class="source-details"><summary>題本版本與來源</summary><p class="source">題本 ${esc(s.form_version)} · ${esc(s.source_file)}<br>${esc(s.source_status)}<br>參照來源：${esc(s.reference_source_file||s.source_file)}</p></details>${referencePanel(s.competency_profile)}${s.items.map((q,i)=>`<fieldset class="question" style="border-left:0;border-right:0;border-bottom:0"><legend class="question-id"><span class="question-number">${String(i+1).padStart(2,'0')}</span><span>${esc(q.dimension_name)}</span></legend><p>${esc(q.prompt)}</p><div class="scale">${Object.entries(s.scale).map(([v,l])=>`<label><input type="radio" name="self-${esc(q.item_id)}" value="${v}" required ${d.answers?.[q.item_id]===Number(v)?'checked':''}>${v} ${esc(l)}</label>`).join('')}</div></fieldset>`).join('')}</div><div class="card"><h2>客觀前測</h2><p class="muted">${esc(s.objective_status||'與自評分開保存；開放題由教師評閱。')}</p>${s.objectives.length?s.objectives.map(q=>`<div class="question"><div class="question-id">${esc(q.item_id)} · ${q.item_type==='single_choice'?'單選':'情境簡答'}</div><p>${esc(q.prompt)}</p>${q.item_type==='single_choice'?q.options.map(o=>`<label class="option"><input type="radio" name="obj-${esc(q.item_id)}" value="${esc(o)}" required ${d.objective_answers?.[q.item_id]===o?'checked':''}><span>${esc(o.replace(/^[A-Z][.、．]\s*/,''))}</span></label>`).join(''):`<textarea aria-label="${esc(q.prompt)}" name="obj-${esc(q.item_id)}" required maxlength="4000">${esc(d.objective_answers?.[q.item_id]||'')}</textarea>`}</div>`).join(''):'<p>此職種尚無可用客觀前測。</p>'}<div class="actions"><span class="muted" id="draft-state">草稿自動保存</span><button type="submit">提交自評，查看分數與分級 →</button></div></div></form>`,1);}
function assessmentValues(){const form=$('#assessment-form'),s=state.entry.snapshot;const data=new FormData(form),answers={},objective_answers={};s.items.forEach(q=>{const v=data.get('self-'+q.item_id);if(v)answers[q.item_id]=Number(v);});s.objectives.forEach(q=>{const v=data.get('obj-'+q.item_id);if(v)objective_answers[q.item_id]=String(v);});return{answers,objective_answers};}
function saveDraft(){if(!$('#assessment-form'))return Promise.resolve();const aid=state.entry.attempt_id,body=assessmentValues();draftQueue=draftQueue.catch(()=>{}).then(()=>api(`/api/assessments/${aid}/draft`,'PUT',body)).then(()=>{if($('#draft-state'))$('#draft-state').textContent='草稿已保存 '+new Date().toLocaleTimeString();});return draftQueue;}
function renderPlacement(r){cleanup();shell(heading('自評分數與學習分級','查看本次分數、分流Level與職種核心指標結果，再進入教案。')+placementPanel(r,esc,competencyRadar)+competencyPanel(r.scores,false),1);}
async function loadSession(sid,view){saveInteractionDraft();cleanup();state.session=await api(`/api/sessions/${sid}`);if(!state.services)state.services=await api('/api/services');const s=state.session;if(s.step>=3&&s.status!=='archived')state.actors=await api(`/api/sessions/${sid}/actors`);if(s.status==='archived'){renderArchive();return;}const step=view||s.step;if(step===2)await renderCases();if(step===3)await renderLearning();if(step===4)await renderInteraction();if(step===5)await renderQuiz();if(step===6)renderReport();}
async function renderCases(){const s=state.session;const cs=await api(`/api/sessions/${s.id}/cases`);shell(heading('Step 2　選擇本輪教案','選定案例後固定內容與評分規準版本，讓每次回饋都能追溯。',`<span class="badge">自評分流 Level ${s.level} · 第 ${s.data.adaptive_plan.completed_practices+1} 次練習</span>`)+`${sourcePanel(cs.find(c=>c.variant))}<div class="note">本輪自評分流 Level ${s.level}，決定案例難度與提示。累積學習 Level ${s.data.adaptive_plan.learning_level??1} 獨立解鎖更多教案資訊，依Level 1→2→3→4→5逐步加入單職類、跨域、一般影片、環景與逐格解說教案，前級內容持續保留。</div><div class="grid2">${cs.map(c=>`<article class="card case-card"><div class="source">${esc(c.id)} · 來源教材轉寫</div><h2>${esc(c.title)}</h2><p>${esc(c.summary)}</p><ul>${c.goals.slice(0,3).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${c.variant?`<div class="note"><b>本職類任務</b><p>${esc(c.variant.role_task)}</p><b>Level ${s.level}支持</b><p>${esc(c.variant.support)}</p><p>達成目標：${esc(c.variant.learner_task)}</p>${c.variant.supplement_tasks.map(t=>`<p>補強：${esc(t)}</p>`).join('')}</div>`:''}<small>來源 ${esc(c.source_file||'既有平台案例')} ${c.source_pages?'p.'+c.source_pages.join('–'):''} · ${esc(c.review_status||'待審')}</small>${clinicalNotes(c.clinical_review,esc)}<div class="note">${(c.learning_path||[]).map(l=>`<p>Level ${l.level} · ${esc(l.title)} · ${l.unlocked?l.lesson_count+'個活動已解鎖':'累積學習後開放'}</p>`).join('')}</div>${(c.paths||[]).map(p=>`<div class="module"><h3>${esc(p.title)} <span class="badge">${p.unlocked?'已解鎖':'未解鎖'}</span></h3><p class="source">${esc(p.requirement)}</p><button data-action="select-case" data-case="${esc(c.id)}" data-path="${p.id}" ${p.unlocked?'':'disabled'}>${p.unlocked?'選擇此教案':'完成條件後解鎖'}</button></div>`).join('')}</article>`).join('')}</div>`,2);}
async function renderLearning(){const s=state.session,l=await api(`/api/sessions/${s.id}/learning`),p=l.plan;const readonly=s.step!==3;const vids=s.data.generated_videos||{};shell(heading('Step 3　影片與情境學習',s.data.case.title,`<span class="badge">${p.video_count} 個學習模組 · 自評 Level ${s.level} · 累積 Level ${p.learning_level??1}</span>`)+`${learningResources(l,s.id)}${characterPanel(state.actors,'lecturer',readonly)}${sourcePanel({variant:l.variant,source_pages:l.source_pages})}<div class="grid3"><div class="card stat"><small>已完成練習</small><strong>${p.completed_practices}<small> 次</small></strong></div><div class="card stat"><small>近期熟練度</small><strong>${p.mastery??p.verified_mastery??'待累積'}<small> / 100</small></strong></div><div class="card stat"><small>目前環境支持</small><strong style="font-size:21px">${({guided:'引導式診間',exploration:'診間探索',team:'跨專業挑戰'})[p.scene_mode]}</strong></div></div><div class="note">${p.access_grant?esc(p.access_grant.note):esc(p.reason)+'。完成至少1輪且熟練度達60分解鎖補強；至少3輪且熟練度達80分解鎖整合挑戰。這是試辦學習路徑規則，不是臨床能力認證。'}</div><div class="grid2"><div class="card"><h2>本輪案例知識</h2>${l.resources?.media?.some(c=>c.projection==='flat'&&c.available)?'<p>一般影片、步驟目的與逐格入口位於上方教材播放器。</p>':(p.learning_level>=3&&l.library_video?.available)?`<video class="video" controls preload="metadata" src="${l.library_video.url}"></video><p class="source">${esc(l.library_video.title)} · 原始教材影片</p>`:'<div class="note warning">情境影片需累積 Level 3 且本教案有對應影片；請依下方職類知識與教案學習。</div>'}<ul>${l.knowledge.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="card"><h2>額外補強模組</h2><p class="source">下列是依練習證據開放的補強路徑，五級教材位於上方漸進教案區。</p>${p.modules.map((m,i)=>`<article class="module"><h3>${i+1}. ${esc(m)} <span class="badge">已解鎖</span></h3><p class="muted">${i===0?'觀察病人背景、疑慮與案例任務。':i===1?'針對溝通與目前弱項練習追問及回覆示教。':'整合個案資料，練習團隊交接與不確定性溝通。'}</p>${vids[i]?.immersive_url?`<p><a class="button" href="${vids[i].immersive_url}" target="_blank" rel="noopener">進入可環顧的3D講師教案 ↗</a></p>`:''}${vids[i]?`${vids[i].actor?.visual_type==='rigged-realistic-3d'?`<video class="video" controls preload="metadata" src="${vids[i].url}"></video>`:`<details><summary>查看舊版影片（歷史證據）</summary><video class="video" controls preload="none" src="${vids[i].url}"></video></details>`}<p class="source">${vids[i].actor?.visual_type==='rigged-realistic-3d'?'教案驅動合成 · 立體骨架角色 · three.js診間 · 中文語音與表情':'歷史版本影片 · 可重新產生擬真版本'}</p>${vids[i].source!=='source_bound_virtual_lecturer'||vids[i].actor?.id!==state.actors.lecturer.id||vids[i].actor?.atlas_sha256!==state.actors.lecturer.atlas_sha256||vids[i].renderer!=='Three.js skinned realistic human v2 / HyperFrames 0.8.185'?`<button class="secondary" data-action="generate-video" data-module="${i}">以目前角色重新產生影片</button>`:''}`:`<button class="secondary" data-action="generate-video" data-module="${i}">產生虛擬講師影片（含語音）</button>`}${!readonly?`<label class="checkline"><input type="checkbox" name="module-done" value="${i}" required>我已完成本模組影片或案例教材學習</label>`:''}</article>`).join('')}<div class="note ${l.video_job?.status==='failed'?'warning':''}" id="video-job">${l.video_job?esc(l.video_job.status==='running'?'影片背景生成中，可繼續閱讀教材…':l.video_job.status==='failed'?l.video_job.error:l.video_job.note):'以本輪教案產生虛擬講師影片，內容與來源版本一起保存。'}</div><p class="source">${esc(l.note)}</p>${(p.paths||[]).filter(x=>!x.unlocked).map(x=>`<div class="module"><h3>尚未解鎖：${esc(x.title)}</h3><p>${esc(x.requirement)}</p></div>`).join('')}</div></div>${informationPanel(l.information,esc)}${clinicalNotes(l.clinical_review,esc)}<div class="card"><h2>觀察與反思</h2><p class="muted">學習完成採學員確認與反思紀錄，並非影片觀看時數或技能操作認證。</p>${readonly?`<p>${esc(s.data.learning?.reflection)}</p><button data-action="back-current">回目前步驟 →</button>`:`<form id="learning-form"><textarea id="reflection" required minlength="10" maxlength="4000" placeholder="請記錄病人的主要疑慮，以及您在互動時想先確認的資訊。"></textarea><label class="checkline"><input id="observed" type="checkbox" required>我已完成上述教材觀察</label><div class="actions"><button type="submit">保存反思，進入虛擬角色互動 →</button></div></form>`}</div>`,3);
await initLearningResources(l.resources);if(l.video_job?.status==='running')videoTimer=setInterval(async()=>{try{const j=await api(`/api/sessions/${s.id}/learning`);if(j.video_job?.status!=='running'){clearInterval(videoTimer);toast(j.video_job?.status==='completed'?'影片已完成':'影片產生失敗，原因已保留');const draft={reflection:$('#reflection')?.value,observed:$('#observed')?.checked,modules:[...document.querySelectorAll('[name=module-done]:checked')].map(x=>x.value)};await loadSession(s.id,3);if($('#reflection'))$('#reflection').value=draft.reflection||'';if($('#observed'))$('#observed').checked=!!draft.observed;document.querySelectorAll('[name=module-done]').forEach(x=>x.checked=draft.modules.includes(x.value));}}catch(e){clearInterval(videoTimer);error(e);}},3000);}
function messagesHtml(messages){return messages.map(m=>{const meta=typeof m.metadata==='string'?JSON.parse(m.metadata||'{}'):m.metadata||{},a=meta.actor;const label=m.role==='user'?'學員'+(a?' → '+(a.display_name||a.name):''):m.source==='ollama'?(meta.mode==='peer'?'AI 虛擬 Level 2 學員':a?`AI ${a.display_name||a.name}`:'AI 虛擬病患'):m.source==='scripted'?'劇本演練（非 AI）':'系統紀錄';return `<div class="bubble ${m.role==='user'?'user':m.role==='system'?'system':''}">${esc(m.content)}${m.role==='assistant'?`<button class="link" type="button" data-action="read-reply" data-mid="${m.id}" data-sid="${m.session_id||state.session?.id||state.teacherDetail?.id}">朗讀回覆</button>`:''}<small>${esc(label)}${a&&m.role!=='user'?' · '+esc(a.title):''} · ${new Date(m.created*1000).toLocaleTimeString()}</small></div>`;}).join('')||'<div class="empty">請先介紹角色，了解對方的疑慮。</div>';}
function actionsHtml(){return `<div class="scene-actions"><button class="secondary" data-action="scene" data-scene="identify">確認互動對象身分</button><button class="secondary" data-action="scene" data-scene="report">查看案例資料</button><button class="secondary" data-action="scene" data-scene="safety">檢查情境安全</button><button class="secondary" data-action="scene" data-scene="handoff">準備團隊交接</button></div>`;}
async function setupAvatar(mode,trust,difficulty){try{const mod=await import('/static/vendor/avatar.bundle.js?v=5.4.0');avatar=mod.createAvatar($('#avatar'),{mode,trust,difficulty,vrmAvailable:state.services?.vrm_available,actor:state.actors?.interaction,onAction:a=>performScene(a).catch(error)});}catch(e){$('#avatar').innerHTML='<div class="scene-fallback">人物模組載入失敗，可使用下方等值場景操作。</div>';}}
async function renderInteraction(){const s=state.session,i=await api(`/api/sessions/${s.id}/interaction`);conversationClosed=i.encounter?.state==='closed';shell(heading('Step 4　面對面情境會談','依教案任務、您的職種與自評難度，與病患或跨專業同仁持續溝通。',`<span class="badge">Level ${s.level}</span>`)+interactionStage(s,i,state.actors,state.services,messagesHtml(actorMessages(s.messages)))+`${i.safety_blocked?`<div class="card"><div class="note warning">本輪出現安全關鍵錯誤，需補強重作後才能交接。原始證據會保留。</div><form id="remediation-form"><label>請說明錯誤風險及下一輪如何修正<textarea required minlength="10" maxlength="4000"></textarea></label><button>保存反思，重新演練</button></form></div>`:''}${s.level===5?'<div class="note">自評 Level 5 將面對困難病患或具有權威壓力的同事，需以專業依據及溝通化解疑慮。另可選擇同儕指導練習：請觀察虛擬 Level 2 學員以常見錯誤選項處理此案例，指出錯誤、示範正確回應，並在交接區記錄 PEARLS 回饋。</div>':''}<div class="card"><h2>H5P 案例界線練習</h2><p class="source">可重試的暖身練習；事件與來源版本保存供教師檢視，分數不併入正式決策評量。</p><iframe class="h5p-frame" title="H5P 案例界線練習" src="/static/h5p.html?session=${s.id}" loading="lazy"></iframe></div><div class="card"><h2>關鍵決策點</h2>${i.questions.map(q=>{const r=i.decisions[q.id];return `<form class="decision-form question" data-item="${esc(q.id)}"><h3>${esc(q.phase)}</h3><p>${esc(q.prompt)}</p>${q.critical?'<span class="badge gold">安全關鍵項目</span>':''}${q.hint?`<details><summary>Level ${s.level}提示</summary><p>${esc(q.hint)}</p></details>`:s.level===3?`<button type="button" class="secondary" data-action="hint" data-item="${esc(q.id)}" ${i.hints_used>=1?'disabled':''}>請求提示（本輪限 1 次）</button><p id="hint-${esc(q.id)}"></p>`:''}${q.options.map(o=>`<label class="option"><input type="radio" name="decision-${esc(q.id)}" value="${o.id}" ${r?.option_id===o.id?'checked':''} ${r?'disabled':'required'}><span>${esc(o.text)}</span></label>`).join('')}${r?`<div class="note">${r.score} / ${r.max_score} 分 · ${esc(r.feedback)}</div>`:'<div class="actions"><button type="submit">確認此決策</button></div>'}</form>`;}).join('')}</div><div class="card"><h2>SBAR 跨專業交接</h2><p class="muted">完成全部決策、指定互動對象各至少兩回合對話後提交。探索或團隊模式另需至少一項場景操作。</p><form id="handoff-form"><div class="sbar">${[['S','目前狀況'],['B','背景資料'],['A','本職類評估'],['R','協助需求及追蹤']].map(([k,l])=>`<label>${k} · ${l}<textarea name="${k}" required minlength="5" maxlength="2000"></textarea></label>`).join('')}</div>${s.level===5?'<details><summary>選修：同儕指導與 PEARLS 回饋</summary><label>若有進行指導練習，可在此保留回饋<textarea name="coaching" minlength="10" maxlength="4000"></textarea></label></details>':''}<div class="actions"><button type="submit">提交交接，進入測驗 →</button></div></form></div>`,4);restoreInteractionDraft();await setupAvatar(i.scene_mode,i.trust,i.difficulty);document.querySelector('.encounter-layout')?.scrollIntoView({block:'start'});disposeScene=mountSceneControls(avatar);setupVoiceInput();$('#chatlog').scrollTop=$('#chatlog').scrollHeight;}
async function performScene(action){const s=state.session;await api(`/api/sessions/${s.id}/scene`,'POST',{action});const text={identify:'請在對話中以合宜方式進行身分確認；此點擊不代表真實辨識已完成。',report:s.data.case.summary,safety:'請評估案例中的安全風險、需要確認的資訊，以及自身專業界線。',handoff:'交接需包含目前狀況、背景、評估與具體協助需求，請於下方填寫 SBAR。'};$('#scene-detail').textContent=text[action];toast('場景操作已保存');}
async function renderQuiz(){const s=state.session,qs=await api(`/api/sessions/${s.id}/quiz`);shell(heading('Step 5　即時測驗','本輪選項與題序重新排列。作答完成後產生客觀練習分，對話與交接由教師覆核。')+`<form id="quiz-form"><div class="card">${qs.map((q,i)=>`<div class="question"><div class="question-id">${i+1} · ${esc(q.id)}</div><h3>${esc(q.question)}</h3>${q.options.map(o=>`<label class="option"><input type="radio" name="${esc(q.id)}" value="${esc(o)}" required><span>${esc(o)}</span></label>`).join('')}</div>`).join('')}<div class="actions"><button type="submit">完成測驗，查看學習成果 →</button></div></div></form>`,5);}
function renderReport(){const s=state.session,r=s.data.result,latest=s.reviews.at(-1),self=JSON.parse(s.assessment?.scores||'{}');shell(heading('Step 6　學習成果與回饋','自評、客觀表現及教師核定結果分開呈現，保留版本與原始證據。',`<span class="badge ${latest?'':'gold'}">${latest?latest.decision==='approve'?'教師已核定':'需補作':'待教師覆核'}</span>`)+`<div class="grid2"><div class="card"><div class="eyebrow">OBJECTIVE PRACTICE SCORE</div><div class="score">${r.objective_score??'待評'}<small style="font-size:18px"> / 100</small></div><p>${esc(r.formula)}</p><div class="row"><span class="badge">決策 ${r.decision_score}</span><span class="badge">後測 ${r.quiz_score}</span></div><div class="note warning">${esc(r.note)}</div></div><div class="card"><h2>教師正式回饋</h2>${latest?`<p>教師 ${esc(latest.teacher)} · ${new Date(latest.created*1000).toLocaleString()}</p><div class="stat"><small>教師整體核定分</small><strong>${latest.score}</strong></div><p>${esc(latest.note)}</p><span class="badge">${latest.decision==='approve'?'核定':'補作建議'} Level ${latest.level}</span>`:'<div class="empty">對話、SBAR 及客觀前測開放題尚待教師檢核。教師核定與自動學習分流分開保存。</div>'}<p class="source">本輪案例分流 Level ${s.level}；本輪結算累積學習 Level ${r.learning_progress?.learning_level??s.level}，教師正式核定另存。</p></div></div><div class="grid2"><div class="card"><h2>入場自評</h2>${competencyPanel(self)}${Object.keys(self.self_dimensions||{}).length?competencyRadar(self.self_dimensions):''}${Object.entries(self.self_dimensions||{}).map(([d,v])=>`<div class="dimbar"><span>${esc(dims[d]||d)}</span><progress value="${v}" max="100"></progress><b>${v}</b></div>`).join('')}<p class="source">反映學員自陳表現；未直接列入客觀表現分。</p></div><div class="card"><h2>本輪學習證據</h2><p>${s.messages.filter(x=>x.role==='user').length} 次對話輸入 · ${Object.keys(s.data.decisions).length} 個決策點 · ${s.data.scene_events.length} 項場景操作</p><p>案例 ${esc(s.data.case.id)}<br>內容版本 ${esc(s.data.content_version)}</p><a href="/api/sessions/${s.id}/export">下載完整訓練 JSON 紀錄</a><div class="actions"><button data-action="refresh-report" class="secondary">重新整理教師回饋</button></div></div></div>${learningNotesEvidence(s.data.learning_notes)}${frameEvidence(s.data.frame_notes,s.data.frame_note_reviews)}<div class="card"><h2>後測解析</h2>${s.data.quiz_result.map(q=>`<details><summary>${q.correct?'✓':'○'} ${esc(q.id)}</summary><p>您的作答：${esc(q.given)}<br>參考答案：${esc(q.answer)}</p><p>${esc(q.explain)}</p></details>`).join('')}</div>${progressPanel(r.learning_progress)}<div class="actions"><button class="secondary" data-action="history">查看學習歷程</button><button data-action="next-round">重新自評，開始下一輪 →</button></div>`,6);}
async function showHistory(){cleanup();const h=await api('/api/history');shell(heading('我的學習歷程','每次訓練與教師核定保留獨立紀錄。重新登入後需先完成本次自評才能續訓。')+assessmentTable(h.assessments)+`<div class="card scrolltable"><table><thead><tr><th>訓練</th><th>職種／主題</th><th>開始 Level</th><th>進度</th><th>更新時間</th><th></th></tr></thead><tbody>${h.sessions.map(s=>`<tr><td>#${s.id}</td><td>${esc(labels[s.profession])} · ${esc(s.topic)}</td><td>${s.level}</td><td>${s.status==='completed'?'已完成':'Step '+s.step}</td><td>${new Date(s.updated*1000).toLocaleString()}</td><td><button data-action="history-entry" data-profession="${s.profession}" data-topic="${esc(s.topic)}" data-sid="${s.id}">查看／續訓</button></td></tr>`).join('')}</tbody></table>${!h.sessions.length?'<div class="empty">尚無學習紀錄</div>':''}</div><button data-action="home">選擇訓練職種</button>`);}
async function teacherOverview(){cleanup();state.teacherDetail=null;const o=await api('/api/teacher/overview');const active=o.sessions.filter(s=>s.status==='active').length,pending=o.sessions.filter(s=>s.status==='completed'&&!s.review).length;shell(heading('教學監控總覽','監看學員進度、虛擬病患互動與評量證據。',`<span class="badge"><span class="live"></span>每 10 秒更新</span>`)+assessmentTable(o.assessments,true)+`<div class="grid3"><div class="card stat"><small>學員帳號</small><strong>${o.students.length}</strong></div><div class="card stat"><small>進行中訓練</small><strong>${active}</strong></div><div class="card stat"><small>待覆核成果</small><strong>${pending}</strong></div></div><div class="card scrolltable"><table><thead><tr><th>學員</th><th>職類／教案</th><th>Level</th><th>進度</th><th>對話</th><th>客觀分</th><th>覆核</th><th></th></tr></thead><tbody>${o.sessions.map(s=>`<tr><td>${esc(s.display_name)}<br><small>${esc(s.username)} · #${s.id}</small></td><td>${esc(labels[s.profession])}<br>${esc(s.case_title||'尚未選教案')}</td><td>${s.level}</td><td>${s.status==='completed'?'已完成':'Step '+s.step}</td><td>${s.turns} 則</td><td>${s.result?.objective_score??'—'}</td><td>${s.review?s.review.decision==='approve'?'已核定':'需補作':'待評'}</td><td><button data-action="teacher-detail" data-sid="${s.id}">監看／覆核</button></td></tr>`).join('')}</tbody></table>${!o.sessions.length?'<div class="empty">尚無訓練紀錄。學員完成首次自評後即會出現。</div>':''}</div><div class="note">${esc(o.note)}</div><div class="card"><h2>教材與系統範圍</h2><p>階段一支援全部 12 職種及 Level 1–5；肌少症既有教案開放營養、物治、放射、醫師及護理 5 職種，其餘職種可選擇上傳教案中的適用情境，合計 9 情境、39 組職種任務。職種分級自評為平台草稿，保留來源與版本供教師審核。</p><button class="secondary" data-action="services">檢查 AI 與語音服務</button><div id="service-detail"></div></div>`);teacherTimer=setInterval(()=>teacherOverview().catch(error),10000);}
async function teacherDetail(sid){cleanup();const d=await api(`/api/teacher/sessions/${sid}`);state.teacherDetail=d;const last=d.reviews.at(-1);shell(heading(`學員訓練 #${sid}`,`${labels[d.profession]} · ${d.topic} · Level ${d.level}`,`<button class="secondary" data-action="home">回監控總覽</button>`)+`<div class="grid2"><div class="card"><h2>互動逐字紀錄</h2><button class="secondary" data-action="teacher-voice">連接 LiveKit 收聽</button><p class="source" id="voice-status">教師僅收聽，不送出病患或學員訊息。</p><div id="teacher-live" class="chatlog">${messagesHtml(d.messages)}</div><p class="source" id="live-updated">更新於 ${new Date().toLocaleTimeString()} · 自動更新不覆寫教師正在填寫的回饋</p></div><div class="card"><h2>訓練進度與評量</h2><p>Step ${d.step} · ${d.status==='completed'?'已完成':'進行中'}<br>${esc(d.data.case?.title||'尚未選教案')}</p>${d.data.result?`<div class="stat"><small>客觀練習分</small><strong>${d.data.result.objective_score}</strong></div><p class="source">${esc(d.data.result.formula)}</p>`:''}<details open><summary>關鍵決策證據</summary>${Object.entries(d.data.decisions||{}).map(([id,r])=>`<p>${esc(id)} · ${r.score}/${r.max_score}<br>${esc(r.feedback)}</p>`).join('')}</details><details><summary>安全補強歷程（${d.data.remediation_history?.length||0} 次）</summary>${(d.data.remediation_history||[]).map(r=>`<p>${new Date(r.at*1000).toLocaleString()} · ${esc(r.reflection)}</p>${Object.entries(r.decisions).map(([id,v])=>`<p>${esc(id)}：${v.score}/${v.max_score} · ${esc(v.feedback)}</p>`).join('')}`).join('')}</details><details open><summary>SBAR 交接</summary>${Object.entries(d.data.sbar?.answers||{}).filter(([k,v])=>!!v).map(([k,v])=>`<p><b>${k}</b> ${esc(v)}</p>`).join('')||'<p>尚未提交</p>'}</details></div></div>${encounterEvidence(d.data.encounter_plan)}${learningNotesEvidence(d.data.learning_notes)}${frameEvidence(d.data.frame_notes,d.data.frame_note_reviews,true)}<div class="card"><h2>角色與 H5P 練習證據</h2><div id="actor-evidence">${trainingEvidence(d.events)}</div><p class="source">H5P 為用戶端回報之練習證據，不併入正式能力分數。</p></div><div class="card"><h2>來源與本次評分規準</h2><p class="source">案例 ${esc(d.data.case?.id)} · ${esc(d.data.content_version)}<br>原始來源 ${esc(d.data.case?.source_file)}<br>案例快照 ${esc(d.data.case_hash)}</p><ul>${(d.data.case?.rubric||[]).map(r=>`<li>${esc(r)}</li>`).join('')}</ul><p class="muted">請依原始對話、決策、SBAR 與前測證據給整體回饋。AI 草稿不自動等同正式評量。</p></div><div class="card"><h2>教師核定與補作</h2>${d.status!=='completed'?'<div class="note warning">學員尚未完成六階段；完成後才能核定。</div>':`<form id="review-form"><div class="grid2"><label>處理方式<select name="decision"><option value="approve">核定回饋</option><option value="revise">需補作／下一輪補強</option></select></label><label>教師整體分數<input name="score" type="number" min="0" max="100" step="0.1" required value="${last?.score??d.data.result.objective_score}"></label><label>教師正式核定 Level<select name="level">${[d.approved_level,Math.min(5,d.approved_level+1)].filter((v,i,a)=>a.indexOf(v)===i).map(n=>`<option value="${n}" ${last?.level===n?'selected':''}>${n===d.approved_level?'維持':'升至'} Level ${n}</option>`).join('')}</select></label><label class="checkline"><input name="safety_pass" type="checkbox">已檢核安全關鍵項目與證據</label></div><label>回饋與核定理由<textarea name="note" required minlength="10" maxlength="4000" placeholder="請指出證據、待補強行為及下一步練習建議。"></textarea></label><input name="expected_review_id" type="hidden" value="${last?.id||0}"><div class="actions"><button type="submit">保存正式教師回饋</button></div></form>`}<h3>覆核歷史</h3>${d.reviews.map(r=>`<p>${esc(r.teacher)} · ${new Date(r.created*1000).toLocaleString()} · ${r.score} 分 · Level ${r.level}<br>${esc(r.note)}</p>`).join('')||'<p class="muted">尚無教師核定</p>'}<a href="/api/sessions/${sid}/export">下載訓練與覆核紀錄 JSON</a></div><div class="card"><h2>歷次自評與前測</h2>${d.assessments.map(a=>`<details><summary>#${a.id} · Level ${a.level} · ${a.completed?'已完成':'草稿'} · ${new Date(a.created*1000).toLocaleString()}</summary><p class="source">${esc(a.snapshot.source_file)} · ${esc(a.snapshot.form_version)} · ${esc(a.snapshot.content_hash)}</p>${a.snapshot.items.map(q=>`<p>${esc(q.prompt)}<br><b>自評 ${a.answers.answers?.[q.item_id]??'未填'} / 5</b></p>`).join('')}${a.snapshot.objectives.map(q=>`<p>${esc(q.prompt)}<br>作答：${esc(a.answers.objective_answers?.[q.item_id]||'未填')}<br><small>參考規準：${esc(q.answer||JSON.stringify(q.rubric||q.expected_keywords))}</small></p>`).join('')}</details>`).join('')}</div>`);teacherTimer=setInterval(async()=>{try{const n=await api(`/api/teacher/sessions/${sid}`);if($('#teacher-live'))$('#teacher-live').innerHTML=messagesHtml(n.messages);if($('#actor-evidence'))$('#actor-evidence').innerHTML=trainingEvidence(n.events);if($('#live-updated'))$('#live-updated').textContent='更新於 '+new Date().toLocaleTimeString()+' · 最新 Step '+n.step+(n.status==='completed'?'，可重新整理後覆核':'');}catch(e){clearInterval(teacherTimer);error(e);}},10000);}

document.addEventListener('input',e=>{if(e.target.closest('#assessment-form')){clearTimeout(draftTimer);draftTimer=setTimeout(()=>saveDraft().catch(error),550);}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,button=form.querySelector('[type=submit]');if(button?.disabled)return;if(button)button.disabled=true;try{
if(await handleStage1Submit(form))return;
if(form.id==='login-form'){state.user=await api('/api/auth/login','POST',{username:$('#username').value,password:$('#password').value});state.services=null;sessionStorage.removeItem('clinical-combo');if(state.user.role==='admin')await adminOverview();else if(state.user.role==='teacher')await teacherOverview();else await chooseProfession();}
if(form.id==='assessment-form'){clearTimeout(draftTimer);await saveDraft();const r=await api(`/api/assessments/${state.entry.attempt_id}/submit`,'POST',assessmentValues());toast('自評分數與分級已保存');renderPlacement(r);}
if(form.id==='remediation-form'){await api(`/api/sessions/${state.session.id}/remediate`,'POST',{reflection:form.querySelector('textarea').value});await loadSession(state.session.id);}
if(form.id==='learning-form'){const modules=[...document.querySelectorAll('[name=module-done]:checked')].map(x=>Number(x.value));await api(`/api/sessions/${state.session.id}/learned`,'POST',{reflection:$('#reflection').value,completed_modules:modules,observed:$('#observed').checked});await loadSession(state.session.id);}
if(form.id==='chat-form')await submitConversation();
if(form.classList.contains('decision-form')){await api(`/api/sessions/${state.session.id}/decision`,'POST',{item_id:form.dataset.item,option_id:new FormData(form).get('decision-'+form.dataset.item)});await loadSession(state.session.id);}
if(form.id==='handoff-form'){const b=Object.fromEntries(new FormData(form));await api(`/api/sessions/${state.session.id}/handoff`,'POST',b);sessionStorage.removeItem(interactionDraftKey());form.remove();await loadSession(state.session.id);}
if(form.id==='quiz-form'){await api(`/api/sessions/${state.session.id}/finish`,'POST',{answers:Object.fromEntries(new FormData(form))});await loadSession(state.session.id);}
if(form.classList.contains('frame-review-form')){const f=new FormData(form),index=Number(form.dataset.noteIndex);try{const r=await api(`/api/teacher/sessions/${state.teacherDetail.id}/frame-notes/${index}/reviews`,'POST',{decision:f.get('decision'),feedback:f.get('feedback'),expected_review_id:form.dataset.expectedReview});const d=state.teacherDetail.data;d.frame_note_reviews??=[];d.frame_note_reviews.push(r);form.closest('[data-frame-note]').outerHTML=frameObservation(d.frame_notes[index],index,d.frame_note_reviews,true);toast('逐格觀察回饋已保存，原始觀察保留');}catch(err){form.querySelector('[data-frame-feedback-status]').textContent=err.message;throw err;}}
if(form.id==='review-form'){const f=new FormData(form);await api(`/api/teacher/sessions/${state.teacherDetail.id}/review`,'POST',{decision:f.get('decision'),score:Number(f.get('score')),level:Number(f.get('level')),safety_pass:f.has('safety_pass'),note:f.get('note'),expected_review_id:Number(f.get('expected_review_id'))});toast('正式教師回饋已保存');await teacherDetail(state.teacherDetail.id);}
}catch(err){error(err);}finally{if(button)button.disabled=false;}});

document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action;b.disabled=true;try{
await handleStage1Action(action,b);
if(action==='characters'){cleanup();const c=await api('/api/characters');shell(heading('虛擬角色設定','立體角色的造型與聲線；每場互動的任務與情緒由教案、等級及會談進展決定。')+characterLibrary(c));}
if(action==='select-actor'){await api(`/api/sessions/${state.session.id}/actors`,'POST',{purpose:b.dataset.purpose,actor_id:b.dataset.actor});await loadSession(state.session.id);toast('角色已保存；病歷資料與既有證據保留');}
if(action==='teacher-voice'){if(voice){await voice.disconnect();voice=null;}else{const c=await api(`/api/sessions/${state.teacherDetail.id}/livekit`,'POST',{}),m=await import('/static/vendor/avatar.bundle.js?v=5.4.0');voice=await m.connectVoice(c,t=>{const el=$('#voice-status');if(el)el.textContent=t;});}}
if(action==='profession-filter')await chooseProfession(b.dataset.filter);
if(action==='toggle-password'){const input=$('#password'),reveal=input.type==='password';input.type=reveal?'text':'password';b.setAttribute('aria-pressed',String(reveal));b.setAttribute('aria-label',reveal?'隱藏密碼':'顯示密碼');}
if(action==='logout'){clearTimeout(draftTimer);if($('#assessment-form'))await saveDraft();await api('/api/auth/logout','POST');sessionStorage.removeItem('clinical-combo');state.user=null;showLogin();}
if(action==='assessment-continue'){await loadSession(Number(b.dataset.session));}
if(action==='home'){if(state.user.role==='admin')await adminOverview();else if(state.user.role==='teacher')await teacherOverview();else await chooseProfession();}
if(action==='topics')await chooseTopics(b.dataset.profession);
if(action==='enter')await enter(b.dataset.profession,b.dataset.topic);
if(action==='select-case'){await api(`/api/sessions/${state.session.id}/case`,'POST',{case_id:b.dataset.case,path_id:b.dataset.path||'core'});await loadSession(state.session.id);}
if(action==='navigate')await loadSession(state.session.id,Number(b.dataset.step));
if(action==='back-current'||action==='refresh-report')await loadSession(state.session.id);
if(action==='history'){if(state.user.role==='admin')await adminOverview();else if(state.user.role==='teacher')await teacherOverview();else await showHistory();}
if(action==='history-entry'){state.entry=await api('/api/entry','POST',{profession:b.dataset.profession,topic:b.dataset.topic});if(state.entry.assessment_required)renderAssessment();else await loadSession(Number(b.dataset.sid));}
if(action==='next-round')await enter(state.session.profession,state.session.topic,true);
if(action==='generate-video'){await api(`/api/sessions/${state.session.id}/video`,'POST',{module:Number(b.dataset.module)});toast('影片工作已在背景啟動');await loadSession(state.session.id,3);}
if(action==='hint'){const r=await api(`/api/sessions/${state.session.id}/hint`,'POST',{item_id:b.dataset.item});$('#hint-'+b.dataset.item).textContent=r.hint;toast('提示使用已保存');}
if(action==='read-reply')playPatientAudio(`/api/sessions/${b.dataset.sid}/speech/${b.dataset.mid}`);
if(action==='stop-speech'){patientAudio?.pause();avatar?.setSpeaking(false);}
if(action==='scene')await performScene(b.dataset.scene);
if(action==='teacher-detail')await teacherDetail(Number(b.dataset.sid));
if(action==='services'){state.services=await api('/api/services');const t=`AI ${state.services.ollama.ready?'可用':'不可用'}；擬真人物 ${state.services.realistic_available?'已安裝':'未安裝'}；LiveKit ${state.services.livekit_configured?'已設定':'未設定'}`;toast(t);if($('#service-detail'))$('#service-detail').textContent=t+'。'+state.services.knowledge_mode;}
if(action==='voice'){if(voiceInput?.enabled)return;if(conversationClosed){toast('請先選擇繼續這場會談或另一位對象。');return;}primePatientAudio();conversationEpoch++;await voiceInput?.start();}
if(action==='voice-finish')voiceInput?.finish();
if(action==='voice-stop'){conversationEpoch++;voiceInput?.stop();patientAudio?.pause();avatar?.setState?.('ready');if($('#presence-state'))$('#presence-state').textContent='語音已取消；逐字稿保留';}
if(action==='conversation-reopen'){await api(`/api/sessions/${state.session.id}/conversation/reopen`,'POST',{});await loadSession(state.session.id);}
if(action==='dictate'){primePatientAudio();await voiceInput?.start();}
}catch(err){error(err);}finally{b.disabled=false;}});

function start(){sessionStorage.removeItem('clinical-combo');showLogin();}
window.addEventListener('pageshow',event=>{if(event.persisted){start();api('/api/auth/logout','POST').catch(error);}});
function renderArchive(){const s=state.session;const old=s.data.legacy_raw||{};shell(heading('舊版歷史訓練紀錄',`訓練 #${s.id} · ${labels[s.profession]} · ${s.topic}`)+`<div class="card"><div class="note warning">此紀錄為 v3 匯入的較早期未完成訓練，以唯讀方式保留。續訓請回首頁選擇相同職種，系統會恢復最新一筆未完成訓練。</div><p>來源 Session ${esc(s.data.legacy_import?.source_session_id)}<br>舊版等級 ${esc(old.baseline_level||'未設定')}（未直接認列新版核定 Level）</p><h2>${esc(s.data.case?.title||'舊版案例')}</h2><div class="chatlog">${messagesHtml(s.messages)}</div><p class="pre">${esc(old.report_text||'未產出報告，原始作答及進度已保存於匯入快照。')}</p><a href="/api/sessions/${s.id}/export">下載歷史證據 JSON</a><div class="actions"><button data-action="home">回訓練首頁</button></div></div>`);}
configureStage1({api,cleanup,shell,heading,esc,state,toast,labels,dims,icon,competencyRadar});
start();


function sourcePanel(c){if(!c?.variant)return '';const v=c.variant;return `<div class="card"><div class="eyebrow">YOUR LEARNING PLAN</div><h2>Level ${v.level}・本輪分級任務</h2><p><b>本級互動壓力：</b>${esc(v.patient_behavior)}</p><p><b>支持方式：</b>${esc(v.support)}</p><p><b>本職類任務：</b>${esc(v.role_task)}</p><p><b>達成目標：</b>${esc(v.learner_task)}</p>${v.supplement_tasks.map(t=>`<p class="note">弱項補強：${esc(t)}</p>`).join('')}<a href="/api/materials/curriculum" target="_blank" rel="noopener">開啟上傳教案原文${c.source_pages?'（p.'+c.source_pages.join('–')+'）':''}</a><p class="source">自評Level決定案例難度；累積學習Level依使用與正確性獨立解鎖教材資訊；教師正式核定另存。教案內容待臨床教師審核。</p></div>`;}
async function chooseTopics(profession){cleanup();const cat=await api('/api/catalog'),courses=cat.courses.filter(c=>c.professions.includes(profession));shell(heading('選擇訓練情境',labels[profession]+'・先完成本次登入自評，再進入本輪訓練。')+`<div class="note">上傳教案共 9 情境，依職種開放 39 組任務；每個情境獨立保存 Level 與續訓進度。</div><div class="grid2">${courses.map(c=>`<article class="card case-card"><div class="eyebrow">${esc(c.id)}</div><h2>${esc(c.title)}</h2><p>${c.has_original_video?'原始教學影片＋':'來源教案閱讀＋'}虛擬講師影片＋AI互動決策</p><p class="source">上傳教案 p.${c.source_pages.join('–')}・${esc(c.review_status)}</p><button data-action="enter" data-profession="${profession}" data-topic="${esc(c.topic)}">進入自評與訓練 →</button></article>`).join('')}</div>${!courses.some(c=>c.topic==='肌少症')?`<div class="card"><h3>肌少症階段一自評</h3><p>此職種沒有肌少症專屬教案，僅保存職種核心指標自評。</p><button class="secondary" data-action="enter" data-profession="${profession}" data-topic="肌少症">僅進行肌少症自評</button></div>`:''}<button class="secondary" data-action="home">回職種首頁</button>`);}

function primePatientAudio(){
 const element=$('#reply-audio');if(!element)return;
 if(patientAudio!==element){patientAudio?.pause();speechContext?.close().catch(()=>{});speechContext=null;patientAudio=element;}
 if(!speechContext){try{speechContext=new AudioContext();const analyser=speechContext.createAnalyser();analyser.fftSize=256;const source=speechContext.createMediaElementSource(element);source.connect(analyser);analyser.connect(speechContext.destination);element._analyser=analyser;}catch{}}
 speechContext?.resume().catch(()=>{});
 if(!element.getAttribute('src')){element.src='data:audio/wav;base64,UklGRiYAAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQIAAACAgA==';element.play().catch(()=>{});}
}
async function playPatientAudio(url){
 primePatientAudio();const current=patientAudio;if(!current)return;voiceInput?.pause();cancelAnimationFrame(speechFrame);current.pause();current.src=url;
 const values=new Uint8Array(256);function sync(){if(current.paused||current.ended)return;current._analyser?.getByteTimeDomainData(values);if(current._analyser){const rms=Math.sqrt(values.reduce((s,v)=>s+((v-128)/128)**2,0)/values.length);avatar?.setAmplitude?.(Math.min(1,rms*7));}speechFrame=requestAnimationFrame(sync);}
 current.onplay=()=>{voiceInput?.pause();avatar?.setSpeaking(true);speechContext?.resume().catch(()=>{});sync();};
 current.onended=()=>{avatar?.setSpeaking(false);if(conversationClosed){voiceInput?.stop();avatar?.setState?.('closed');}else if($('#voice-auto')?.checked)voiceInput?.resume();};
 current.onerror=()=>{voiceInput?.stop();avatar?.setSpeaking(false);if($('#voice-status'))$('#voice-status').textContent='角色語音載入失敗，請點「朗讀回覆」重試。';};
 try{await current.play();if($('#voice-status')){$('#voice-status').textContent='角色回覆中…';$('#voice-status').dataset.state='speaking';}}catch{toast('請點角色語音播放列的播放鍵，啟動聲音。');if($('#voice-status'))$('#voice-status').textContent='瀏覽器暫停自動播放；請按播放鍵，播放完畢後會接續收音。';}
}
function setupVoiceInput(){
 voiceInput?.dispose();voiceInput=createVoiceInput({sid:state.session.id,onText:text=>{if(conversationClosed||chatBusy||!$('#chat-text'))return;$('#chat-text').value=text;saveInteractionDraft();if($('#voice-auto')?.checked)$('#chat-form').requestSubmit();else $('#voice-status').textContent='辨識完成，請確認文字後送出。';},onStatus:(t,phase)=>{if($('#voice-status'))$('#voice-status').textContent=t;avatar?.setState?.(phase==='transcribing'?'thinking':phase==='listening'?'listening':'ready');if($('#presence-state'))$('#presence-state').textContent=phase==='listening'?'正在聽您說':phase==='transcribing'?'正在理解您的話':t;const b=document.querySelector('[data-action="voice"]');if(b){b.disabled=!!voiceInput?.enabled;b.textContent=voiceInput?.enabled?'會談進行中':'我要對話溝通';}},onError:error,beforeListen:()=>{patientAudio?.pause();avatar?.setSpeaking(false);},onListening:v=>{if(v)avatar?.setState?.('listening');}});
 $('#voice-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;voiceInput.pause();$('#voice-status').textContent='正在本機辨識匯入語音…';try{const response=await fetch(`/api/sessions/${state.session.id}/transcribe`,{method:'POST',headers:{'Content-Type':file.type||'audio/wav'},body:file});const r=await response.json();if(!response.ok)throw Error(r.detail);$('#chat-text').value=r.text;$('#voice-status').textContent='辨識完成，請確認文字後送出。';saveInteractionDraft();}catch(e){error(e);$('#voice-status').textContent=e.message;}finally{e.target.value='';}};
}

async function submitConversation(){
 if(chatBusy||conversationClosed)return;
 const text=$('#chat-text').value.trim();if(!text)return;
 const run=conversationEpoch,sid=state.session.id;chatBusy=true;
 primePatientAudio();voiceInput?.pause();avatar?.setState?.('thinking');
 $('#chat-state').textContent='對方正在回應…';$('#presence-state').textContent='正在思考您的話';
 try{
  const r=await api(`/api/sessions/${sid}/chat`,'POST',{text,mode:$('#chat-mode').value,request_id:crypto.randomUUID()});
  if(!$('#chat-form')||state.session?.id!==sid||run!==conversationEpoch)return;
  const n=await api(`/api/sessions/${sid}`);if(!$('#chat-form')||run!==conversationEpoch)return;
  state.session=n;$('#chatlog').innerHTML=messagesHtml(actorMessages(n.messages));$('#chatlog').scrollTop=$('#chatlog').scrollHeight;
  if(!r.ok){voiceInput?.stop();$('#chat-state').textContent=r.error;toast('AI 未完成回覆；輸入已保存。請確認服務後再開始。');return;}
  $('#chat-text').value='';saveInteractionDraft();const c=conversationState(r);conversationClosed=c.closed;
  $('#chat-state').textContent=c.label;$('#presence-state').textContent=c.label;$('#current-reply').textContent=r.text;
  avatar?.setEmotion?.(c.emotion);$('#conversation-end').hidden=!c.closed;
  if($('#speak').checked&&r.audio_url)await playPatientAudio(r.audio_url);
  else if(c.closed){voiceInput?.stop();avatar?.setState?.('closed');}
  else if($('#voice-auto')?.checked)voiceInput?.resume();
 }catch(e){voiceInput?.stop();avatar?.setState?.('ready');throw e;}
 finally{chatBusy=false;}
}

function interactionDraftKey(){return `clinical-interaction-${state.user?.id}-${state.session?.id}`;}
function saveInteractionDraft(){const form=$('#handoff-form');if(!form||!state.session)return;sessionStorage.setItem(interactionDraftKey(),JSON.stringify({sbar:Object.fromEntries(new FormData(form)),chat:$('#chat-text')?.value||''}));}
function restoreInteractionDraft(){try{const d=JSON.parse(sessionStorage.getItem(interactionDraftKey())||'null');if(!d)return;for(const [key,value] of Object.entries(d.sbar||{})){const el=document.querySelector(`#handoff-form [name="${key}"]`);if(el)el.value=value;}if($('#chat-text'))$('#chat-text').value=d.chat||'';}catch{}}
document.addEventListener('input',event=>{if(event.target.closest('#handoff-form')||event.target.id==='chat-text')saveInteractionDraft();});

function trainingEvidence(events){const kinds={actor_selected:'角色切換',h5p_practice:'H5P 暖身練習',voice_published:'語音回覆'},verbs={attempted:'開啟練習',interacted:'選擇答案',answered:'提交答案'};const rows=(events||[]).filter(e=>Object.hasOwn(kinds,e.kind)).map(e=>({...e,data:typeof e.data==='string'?JSON.parse(e.data):e.data})).filter(e=>e.kind!=='h5p_practice'||e.data.verb!=='attempted');return rows.slice(-10).reverse().map(e=>{const x=e.data;return `<p class="evidence-row"><b>${esc(kinds[e.kind])}</b> · ${esc(x.actor?.name||x.actor_name||'')} · ${esc(verbs[x.verb]||'')}${x.result?.score?' · 練習 '+esc(x.result.score.raw)+' / '+esc(x.result.score.max):''}<br><small>${new Date(e.created*1000).toLocaleString()} · 來源 ${esc((x.content_version||x.case_hash||'').slice(0,12))}</small></p>`;}).join('')||'<p>尚無角色或練習紀錄。完整來源與事件可由下方訓練證據 JSON 匯出。</p>';}

function actorMessages(messages){const aid=state.actors?.interaction?.id;return messages.filter(m=>{const meta=typeof m.metadata==='string'?JSON.parse(m.metadata||'{}'):m.metadata||{};return !meta.actor||meta.actor.id===aid;});}
